ut class="field mt-2" name="model" value="{{ old('model') }}"></label><label class="text-sm">Odometer (km)<input class="field mt-2" type="number" min="0" name="odometer_km" value="{{ old('odometer_km') }}"></label></div></div><div class="panel p-6"><h2 class="text-xl font-bold">3. Lokasi layanan</h2><label class="block text-sm mt-4">Alamat lengkap<textarea class="field mt-2" name="address" id="address" rows="3" placeholder="Jalan, nomor rumah, kecamatan">{{ old('address') }}</textarea></label><div class="flex flex-wrap gap-3 mt-3"><button type="button" id="use-location" class="rounded-xl border border-slate-600 px-4 py-2 text-sm font-bold">Gunakan lokasi GPS</button><span id="gps-message" class="muted text-sm self-center"></span></div><div id="checkout-map" class="h-64 rounded-xl mt-4"></div><input type="hidden" name="latitude" id="latitude" value="{{ old('latitude') }}"><input type="hidden" name="longitude" id="longitude" value="{{ old('longitude') }}"><p class="muted text-xs mt-2">Peta membutuhkan internet. Kamu dapat menekan peta untuk memilih titik lokasi.</p><label class="block text-sm mt-4">Catatan untuk mekanik<textarea class="field mt-2" name="notes" rows="2">{{ old('notes') }}</textarea></label></div><div class="panel p-6"><h2 class="text-xl font-bold">4. Pembayaran</h2><label class="flex items-start gap-3 border border-slate-700 rounded-xl p-4 mt-4"><input type="radio" name="payment_method" value="midtrans" checked><span><b>Midtrans Snap</b><span class="block muted text-sm mt-1">Pilih QRIS, transfer bank, atau e-wallet di halaman pembayaran. Butuh kredensial Sandbox.</span></span></label><label class="flex items-start gap-3 border border-slate-700 rounded-xl p-4 mt-3"><input type="radio" name="payment_method" value="cod" @checked(old('payment_method')==='cod')><span><b>Bayar di tempat</b><span class="block muted text-sm mt-1">Pembayaran ditangani saat servis sesuai kebijakan demo.</span></span></label></div></div><aside class="panel p-6 h-fit lg:sticky lg:top-24"><h2 class="text-xl font-bold">Ringkasan</h2><div class="space-y-4 mt-5">@foreach($items as $item)<div class="flex justify-between gap-4 text-sm"><span>{{ $item['name'] }} × {{ $item['quantity'] }}</span><b>Rp{{ number_format($item['line'],0,',','.') }}</b></div>@endforeach</div><hr class="border-slate-700 my-5"><div class="flex justify-between text-sm muted"><span>Subtotal</span><span>Rp{{ number_format($subtotal,0,',','.') }}</span></div><div class="flex justify-between text-sm muted mt-2"><span>Biaya kunjungan</span><span id="visit-fee">Rp25.000</span></div><div class="flex justify-between text-xl font-black mt-5"><span>Total estimasi</span><span class="text-orange-400" id="total">Rp{{ number_format($subtotal+25000,0,',','.') }}</span></div><button class="btn w-full mt-6">Buat pesanan ↗</button><p class="muted text-xs mt-4">Harga dihitung ulang di server. Stok sparepart dikunci saat transaksi diproses.</p></aside></form></section>@endsection
@push('scripts')<script>
const vehicleSelect=document.getElementById('vehicle_id'), newVehicle=document.getElementById('new-vehicle');function toggleVehicle(){if(vehicleSelect){newVehicle.style.display=vehicleSelect.value?'none':'grid';}}if(vehicleSelect){vehicleSelect.addEventListener('change',toggleVehicle);toggleVehicle();}
const fee=document.getElementById('visit-fee'),total=document.getElementById('total'),subtotal={{ (int)$subtotal }};document.querySelectorAll('[name="service_type"]').forEach(el=>el.addEventListener('change',()=>{const home=document.querySelector('[name="service_type"]:checked').value==='home';fee.textContent=home?'Rp25.000':'Rp0';total.textContent='Rp'+(subtotal+(home?25000:0)).toLocaleString('id-ID');}));
const latInput=document.getElementById('latitude'),lngInput=document.getElementById('longitude'),gpsMessage=document.getElementById('gps-message');let map,marker;if(window.L){const initial=[parseFloat(latInput.value)||-6.2,parseFloat(lngInput.value)||106.816666];map=L.map('checkout-map').setView(initial, latInput.value?15:5);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'© OpenStreetMap'}).addTo(map);function setPoint(lat,lng){latInput.value=lat.toFixed(7);lngInput.value=lng.toFixed(7);if(marker)marker.setLatLng([lat,lng]);else marker=L.marker([lat,lng],{draggable:true}).addTo(map);marker.on('dragend',e=>{const p=e.target.getLatLng();latInput.value=p.lat.toFixed(7);lngInput.value=p.lng.toFixed(7)});map.setView([lat,lng],15);}if(latInput.value&&lngInput.value)setPoint(initial[0],initial[1]);map.on('click',e=>setPoint(e.latlng.lat,e.latlng.lng));document.getElementById('use-location').addEventListener('click',()=>{if(!navigator.geolocation){gpsMessage.textContent='Browser tidak mendukung GPS.';return;}gpsMessage.textContent='Meminta izin lokasi…';navigator.geolocation.getCurrentPosition(p=>{setPoint(p.coords.latitude,p.coords.longitude);gpsMessage.textContent='Lokasi berhasil dipilih.';},()=>gpsMessage.textContent='Lokasi gagal dibaca. Izinkan akses GPS atau pilih di peta.',{enableHighAccuracy:true,timeout:10000});});}else{document.getElementById('checkout-map').innerHTML='<p class="p-4 muted">Peta tidak dapat dimuat. Masukkan koordinat jika diperlukan.</p>';}
</script>@endpush
